<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,Arial,sans-serif;font-size:10px;color:#1f2937}header{background:#9b4444;color:#fff;padding:18px}h1{margin:8px 0 0;font-size:18px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #cbd5e1;padding:5px;text-align:left}th{background:#eef1f4;font-size:8px}</style></head><body><header><strong>SAN JUAN CITY DISASTER RISK REDUCTION AND MANAGEMENT DEPARTMENT</strong><br><em>Monitoring and Tracking Status for Rescue Vehicles</em><h1>{{ strtoupper($vehicle->call_sign) }}</h1></header><table><tr><th>Vehicle</th><td>{{ $vehicle->brand }} {{ $vehicle->vehicle_model }}</td><th>Plate No.</th><td>{{ $vehicle->plate_number }}</td><th>Team</th><td>{{ $vehicle->team }}</td></tr></table><table><thead><tr><th>No.</th><th>Task / Service</th><th>Frequency</th><th>Responsible Person</th><th>Status</th></tr></thead><tbody>@foreach($vehicle->tasks as $index => $task)<tr><td>{{ $index + 1 }}</td><td>{{ $task->task_name ?: '—' }}</td><td>{{ $task->frequency }}</td><td>{{ $task->responsiblePerson?->full_name ?: $task->responsible_name }}</td><td>{{ ucfirst($task->status) }}</td></tr>@endforeach</tbody></table></body></html>